const fill = (n, i, l, t) => i == l - 1 && has(t, 'K') && n != 'outro'
const tri = (x) => 1 - Math.abs(2 * x - 1)
const r2 = (x) => Math.round(x * 100) / 100

// ---- drums (bar variants: [main, phrase-end variation, section-end fill])
